<link rel="stylesheet" href="<?=asset('css/views/formulas.css')?>"><div class="page-heading"><div><span class="eyebrow">Motor clínico</span><h1>Fórmulas médicas</h1><p>Versionado, variables y publicación de cálculos.</p></div><?php if(can('formulas.crear')):?><button class="btn btn-primary" data-modal-open="formula-create">＋ Nueva fórmula</button><?php endif;?></div><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="cards-grid"><?php foreach($formulas as $f):?><article class="soft-panel"><div class="inline-actions"><strong>🧮 <?=e($f['nombre'])?></strong><span class="status-badge status-neutral">v<?=e($f['ultima_version']??'—')?> · <?=e($f['ultimo_estado']??'—')?></span></div><p class="text-muted"><?=e($f['descripcion']??'')?></p><p><code><?=e($f['codigo'])?></code> · Resultado <?=e($f['unidad']??'sin unidad')?></p><?php if(can('formulas.crear')):?><button class="btn btn-secondary btn-sm" data-version-formula="<?=$f['id']?>">Nueva versión</button><?php endif;?></article><?php endforeach;?></div><div class="modal" id="formula-create"><div class="modal-backdrop"></div><div class="modal-dialog modal-xl"><div class="modal-header"><h2>Nueva fórmula</h2><button class="modal-close" data-modal-close>×</button></div><form method="POST" action="<?=url('/formulas')?>"><?=csrf_field()?><div class="modal-body"><div class="form-grid"><label><span>Código</span><input name="codigo" required placeholder="DOSIS_MG"></label><label><span>Nombre</span><input name="nombre" required></label><label><span>Categoría</span><select name="categoria_formula_id"><?php foreach($categories as $x):?><option value="<?=$x['id']?>"><?=e($x['nombre'])?></option><?php endforeach;?></select></label><label><span>Unidad resultado</span><select name="unidad_resultado_id"><option value="">Sin unidad</option><?php foreach($units as $x):?><option value="<?=$x['id']?>"><?=e($x['simbolo'].' · '.$x['nombre'])?></option><?php endforeach;?></select></label><label class="field-full"><span>Descripción</span><textarea name="descripcion"></textarea></label><label class="field-full"><span>Expresión</span><input name="expresion" required placeholder="PESO * DOSIS"></label></div><h3>Variables</h3><div id="formula-vars" class="stack"><div class="form-grid soft-panel"><label><span>Código</span><input name="variables[0][codigo]" placeholder="PESO"></label><label><span>Etiqueta</span><input name="variables[0][etiqueta]" placeholder="Peso"></label><label><span>Tipo</span><select name="variables[0][tipo_variable_id]"><?php foreach($variableTypes as $x):?><option value="<?=$x['id']?>"><?=e($x['nombre'])?></option><?php endforeach;?></select></label><label><span>Origen</span><select name="variables[0][origen_variable_id]"><?php foreach($variableOrigins as $x):?><option value="<?=$x['id']?>"><?=e($x['nombre'])?></option><?php endforeach;?></select></label><label><span>Unidad</span><select name="variables[0][unidad_medida_id]"><option value="">—</option><?php foreach($units as $x):?><option value="<?=$x['id']?>"><?=e($x['simbolo'])?></option><?php endforeach;?></select></label><label><span>Obligatoria</span><select name="variables[0][obligatorio]"><option value="1">Sí</option><option value="0">No</option></select></label></div></div></div><div class="modal-footer"><button class="btn btn-primary">Crear fórmula</button></div></form></div></div><script>document.querySelectorAll('[data-version-formula]').forEach(b=>b.addEventListener('click',()=>{const e=prompt('Expresión de la nueva versión');if(!e)return;const f=document.createElement('form');f.method='POST';f.action='<?=e(url('/formulas'))?>/'+b.dataset.versionFormula+'/versiones';f.innerHTML='<?=str_replace("'","\\'",csrf_field())?>'+'<input type="hidden" name="expresion" value="'+e.replaceAll('&','&amp;').replaceAll('"','&quot;')+'">';document.body.appendChild(f);f.submit();}));</script>
